mapper.select:
select c.commission_id, c.from_member_id, fm.phone as from_phone, c.to_member_id, tm.phone as to_phone,
       c.team_level, c.currency, c.base_amount, c.rate, c.amount, c.recharge_id, c.create_time
from biz_commission_log c
left join biz_member fm on fm.member_id = c.from_member_id
left join biz_member tm on tm.member_id = c.to_member_id

    and (c.from_member_id = #{memberId} or c.to_member_id = #{memberId})
    and c.from_member_id = #{fromMemberId}
    and c.to_member_id = #{toMemberId}
    and c.currency = #{currency}
    and c.team_level = #{teamLevel}
    and (fm.phone like concat('%', #{phone}, '%') or tm.phone like concat('%', #{phone}, '%'))
    and c.create_time >= #{params.beginTime}
    and c.create_time < date_add(#{params.endTime}, interval 1 day)

order by c.commission_id desc

mapper.insert:
insert into biz_commission_log (
    from_member_id, to_member_id, team_level, currency, base_amount, rate, amount, recharge_id, create_time
) values (
    #{fromMemberId}, #{toMemberId}, #{teamLevel}, #{currency}, #{baseAmount}, #{rate}, #{amount}, #{rechargeId}, sysdate()
)
